<template><main class="detail-page"><el-button link @click="router.push('/admin/public-models')">← {{ t('publicModelsAdmin.back') }}</el-button><el-skeleton v-if="loading && !model" :rows="8" animated/><el-alert v-else-if="detailError" ref="errorAlert" role="alert" type="error" :closable="false" :title="detailErrorTitle"><p v-if="detailError.requestId">{{ t('publicModelsAdmin.requestId') }}: <code>{{ detailError.requestId }}</code></p><el-button link @click="refresh">{{ t('publicModelsAdmin.refresh') }}</el-button></el-alert><template v-else-if="model"><header><div><p class="eyebrow">{{ model.provider }}</p><h1 tabindex="-1">{{ model.displayName }}</h1><code>{{ model.modelKey }}</code></div><div class="actions"><el-button :disabled="modelSaving || statusSaving || deleteSaving" @click="showEdit=true">{{ t('publicModelsAdmin.edit') }}</el-button><el-button v-if="model.status==='active'" :loading="statusSaving" :disabled="statusSaving || modelSaving || deleteSaving" @click="openDeactivate">{{ t('publicModelsAdmin.inactivate') }}</el-button><el-button v-else :loading="statusSaving" :disabled="statusSaving || modelSaving || deleteSaving" @click="activate">{{ t('publicModelsAdmin.activate') }}</el-button><el-dropdown @command="command"><el-button ref="moreTrigger" :disabled="modelSaving || statusSaving || deleteSaving" :aria-label="t('publicModelsAdmin.more')">•••</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="delete" class="danger">{{ t('publicModelsAdmin.delete') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><el-descriptions border :column="2"><el-descriptions-item :label="t('publicModelsAdmin.upstreamModelId')"><code>{{ model.upstreamModelId }}</code></el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.status')">{{ t(`publicModelsAdmin.statuses.${model.status}`) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.contextWindow')">{{ model.contextWindow }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.publicDisplayGroup')">{{ model.publicDisplayGroup||t('publicModelsAdmin.notSet') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.capabilities')">{{ model.capabilities.join(', ')||t('publicModelsAdmin.none') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.endpointTypes')">{{ model.endpointTypes.join(', ')||t('publicModelsAdmin.none') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.publicRestrictions')">{{ model.publicRestrictions.join(', ')||t('publicModelsAdmin.none') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.inputPrice')">{{ price(model.inputPriceUsdPerMillionTokens) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.outputPrice')">{{ price(model.outputPriceUsdPerMillionTokens) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.priceSource')">{{ model.priceSource||t('publicModelsAdmin.notSet') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.priceReviewer')">{{ model.priceReviewer||t('publicModelsAdmin.notSet') }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.priceEffectiveAt')">{{ time(model.priceEffectiveAt) }}</el-descriptions-item><el-descriptions-item :label="t('publicModelsAdmin.revision')">{{ model.revision }}</el-descriptions-item></el-descriptions></template>
  <el-alert v-if="mutationError && !conflictComparison" class="mutation-error" role="alert" type="error" :closable="false" :title="mutationErrorTitle"><p v-if="mutationError.requestId">{{ t('publicModelsAdmin.requestId') }}: <code>{{ mutationError.requestId }}</code></p></el-alert>
  <el-alert v-if="conflictComparison" class="conflict" role="alert" type="warning" :closable="false" :title="t('publicModelsAdmin.conflict')"><dl><template v-for="row in conflictRows" :key="row.key"><dt>{{ fieldLabel(row.key) }}</dt><dd>{{ row.before }} → {{ row.attempted }} → {{ row.latest }}</dd></template></dl></el-alert>
  <p class="sr-only" aria-live="polite">{{ loading?t('publicModelsAdmin.loading'):'' }}</p><PublicModelForm v-model="showEdit" mode="edit" :model="model" :busy="modelSaving" :error="formError" @submit="update" />
  <el-dialog v-model="showDeactivate" :close-on-click-modal="false" :title="t('publicModelsAdmin.inactivate')"><el-input v-model="deactivateReason" maxlength="128"/><template #footer><el-button @click="showDeactivate=false">{{t('publicModelsAdmin.cancel')}}</el-button><el-button type="warning" :loading="statusSaving" :disabled="statusSaving" @click="deactivate">{{t('publicModelsAdmin.confirm')}}</el-button></template></el-dialog>
  <el-dialog v-model="showDelete" :close-on-click-modal="false" @closed="restoreDeleteFocus" :title="t('publicModelsAdmin.delete')"><el-alert type="warning" :closable="false" :title="t('publicModelsAdmin.permanentWarning')"/><el-form label-position="top"><el-form-item :label="t('publicModelsAdmin.reason')"><el-input v-model="deleteForm.reason" maxlength="128"/></el-form-item><el-form-item :label="t('publicModelsAdmin.currentPassword')"><el-input v-model="deleteForm.currentPassword" type="password" autocomplete="current-password"/></el-form-item></el-form><template #footer><el-button @click="closeDelete">{{t('publicModelsAdmin.cancel')}}</el-button><el-button type="danger" :loading="deleteSaving" :disabled="deleteSaving||!deleteForm.reason||!deleteForm.currentPassword" @click="remove">{{t('publicModelsAdmin.confirmDelete')}}</el-button></template></el-dialog>
</main></template>
<script setup>
import { computed,nextTick,onBeforeUnmount,reactive,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { usePublicModelAdminStore } from '@/stores/publicModelAdmin';import { useI18n } from '@/composables/useI18n';import PublicModelForm from '@/components/public-admin/PublicModelForm.vue'
const route=useRoute(),router=useRouter(),store=usePublicModelAdminStore(),{t}=useI18n();const moreTrigger=ref(null);const showEdit=ref(false),showDeactivate=ref(false),showDelete=ref(false),deactivateReason=ref(''),formError=ref(''),conflictComparison=ref(null);const deleteForm=reactive({reason:'',currentPassword:''});const model=computed(()=>store.detail),loading=computed(()=>store.detailLoading),detailError=computed(()=>store.detailError),mutationError=computed(()=>store.mutationError),modelSaving=computed(()=>store.modelSaving),statusSaving=computed(()=>store.statusSaving),deleteSaving=computed(()=>store.deleteSaving);const knownErrors=new Set(['authentication_required','root_required','not_found','gone','revision_conflict','validation_failed','unavailable','network_error']);const safeErrorTitle=value=>t(`publicModelsAdmin.errors.${knownErrors.has(value?.code)?value.code:'request_failed'}`);const detailErrorTitle=computed(()=>safeErrorTitle(detailError.value)),mutationErrorTitle=computed(()=>safeErrorTitle(mutationError.value));const expectedRevision=computed(()=>model.value?.revision);const stringify=v=>Array.isArray(v)?v.join(', '):String(v??t('publicModelsAdmin.notSet'));const conflictRows=computed(()=>{const c=conflictComparison.value;if(!c)return[];return Object.keys(c.attempted).filter(key=>key!=='expectedRevision').map(key=>({key,before:stringify(c.before?.[key]),attempted:stringify(c.attempted[key]),latest:stringify(c.latest?.[key])}))});const fieldLabel=key=>t(`publicModelsAdmin.fields.${Object.hasOwn(FIELD_LABELS,key)?key:'unknown'}`);const FIELD_LABELS={displayName:1,provider:1,capabilities:1,contextWindow:1,inputPrice:1,outputPrice:1,publicDisplayGroup:1,endpointTypes:1,publicRestrictions:1,priceSource:1,priceReviewer:1,priceEffectiveAt:1,status:1}
async function refresh(){const guid=String(route.params.guid);store.clearDetail();await store.loadDetail(guid)}
function currentModel(){const guid=String(route.params.guid);return model.value?.guid===guid?model.value:null}
async function conflictAware(work,attempted={}){const before=currentModel();if(!before)return null;const snapshot={...before};const out=await work();if(store.mutationError?.code==='revision_conflict'){showEdit.value=false;showDeactivate.value=false;showDelete.value=false;deleteForm.currentPassword='';ElMessage.warning(t('publicModelsAdmin.conflict'));await refresh();conflictComparison.value={before:snapshot,attempted,latest:currentModel()?{...currentModel()}:null}}return out}
async function update(form){const current=currentModel();if(!current||store.modelSaving)return;formError.value='';const out=await conflictAware(()=>store.update(current.guid,form,current),form);if(out){showEdit.value=false;conflictComparison.value=null}else formError.value=mutationErrorTitle.value}
async function activate(){const current=currentModel();if(!current||store.statusSaving)return;await conflictAware(()=>store.activate(current.guid,current.revision),{status:'active'})}
function openDeactivate(){deactivateReason.value='';showDeactivate.value=true}
async function deactivate(){const current=currentModel();if(!current||!deactivateReason.value||store.statusSaving)return;const out=await conflictAware(()=>store.deactivate(current.guid,current.revision,deactivateReason.value),{status:'inactive'});if(out)showDeactivate.value=false}
function command(value){if(value==='delete'&&currentModel())showDelete.value=true}
function closeDelete(){deleteForm.currentPassword='';deleteForm.reason='';showDelete.value=false}
function restoreDeleteFocus(){nextTick(()=>moreTrigger.value?.$el?.focus?.()??moreTrigger.value?.focus?.())}
async function remove(){const current=currentModel();if(!current||store.deleteSaving)return;const input={guid:current.guid,expectedRevision:current.revision,reason:deleteForm.reason,currentPassword:deleteForm.currentPassword};const pending=store.remove(input);deleteForm.currentPassword='';try{const out=await conflictAware(()=>pending,{status:'deleted'});if(out)await router.replace('/admin/public-models')}finally{deleteForm.currentPassword=''}}
const price=v=>v===null?t('publicModelsAdmin.notSet'):'$'+v+' USD / 1M tokens';const time=v=>v===null?t('publicModelsAdmin.notSet'):new Date(v).toLocaleString();watch(()=>route.params.guid,()=>{closeDelete();showEdit.value=false;showDeactivate.value=false;conflictComparison.value=null;store.clearMutationError();void refresh()},{immediate:true});onBeforeUnmount(()=>{deleteForm.currentPassword='';store.cancel();store.clearDetail()})
</script>
<style scoped>.detail-page{max-width:1100px;margin:auto;padding:24px;height:100%;overflow:auto}header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin:24px 0}.actions{display:flex;gap:8px}.eyebrow{color:var(--text-secondary)}code{font-family:ui-monospace,monospace}.danger{color:var(--el-color-danger)}.conflict{margin:18px 0}.conflict dl{display:grid;grid-template-columns:max-content 1fr;gap:6px 12px}.conflict dd{margin:0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:700px){.detail-page{padding:16px}header{flex-direction:column}.actions{width:100%;flex-wrap:wrap}.detail-page :deep(.el-descriptions__body){overflow:auto}.conflict dl{grid-template-columns:1fr}}</style>
